class Command(BaseCommand):
    @transaction.atomic
    def handle(self, *args, **kwargs):
        created, updated = 0, 0

        for item in FAQS:
            obj, was_created = FAQ.objects.update_or_create(
                page=item["page"],
                question=item["question"],

                defaults={
                    "category": item["category"],
                    "answer": item["answer"],
                    "keywords": item["keywords"],
                    "is_active": True,
                }
            )

            if was_created:
                created += 1
            else:
                updated += 1

        self.stdout.write(
            self.style.SUCCESS(
                f"FAQs seeded successfully. Created: {created}, Updated: {updated}, Total: {len(FAQS)}"
            )
        )

# Run Command: python manage.py seed_faqs